/* ============================================
   BANNER COMPONENT
   Full-width page-level status strip
   ============================================ */

.ds-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-500);
  width: 100%;
  padding: var(--padding-200) var(--padding-500);
}

.ds-banner__body {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
}

.ds-banner--center .ds-banner__body {
  flex: 1;
  justify-content: center;
}

.ds-banner__icon {
  --icon-size: var(--icon-size-500);
  flex-shrink: 0;
}

.ds-banner__content {
  margin: 0;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

.ds-banner__title {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
}

.ds-banner__action {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}

/* ============================================
   DISMISS
   ============================================ */

.ds-banner__dismiss {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--padding-100);
  border: none;
  background: none;
  color: inherit;
  cursor: pointer;
  border-radius: var(--radius-pill);
  flex-shrink: 0;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-banner__dismiss .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-banner__dismiss:hover {
  opacity: 0.7;
}

.ds-banner__dismiss:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* ============================================
   VARIANTS
   ============================================ */

.ds-banner--info {
  background-color: var(--color-status-info-bg);
  color: var(--color-status-info-text);
}

.ds-banner--positive {
  background-color: var(--color-status-positive-bg);
  color: var(--color-status-positive-text);
}

.ds-banner--warning {
  background-color: var(--color-status-warning-bg);
  color: var(--color-status-warning-text);
}

.ds-banner--error {
  background-color: var(--color-status-error-bg);
  color: var(--color-status-error-text);
}

.ds-banner--neutral {
  background-color: var(--color-status-neutral-bg);
  color: var(--color-status-neutral-text);
}

import React from 'react';
import './Banner.css';
import '../../fonts/material-symbols.css';

/** Props owned by Banner itself — everything else falls through to the root node. */
type BannerOwnProps = {
  /** Status variant determines colour and default icon */
  variant?: 'info' | 'positive' | 'warning' | 'error' | 'neutral';
  /** Short leading emphasis before the body text. Deliberately shadows the native `title` attribute — a banner never needs a hover tooltip. */
  title?: string;
  /** Banner body content — a single line of text, rendered inside the banner's paragraph */
  children?: React.ReactNode;
  /** Custom icon override — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Action slot on the trailing edge, for a compact Button or link */
  action?: React.ReactNode;
  /** Whether the banner shows a dismiss button */
  dismissible?: boolean;
  /** Callback when the dismiss button is clicked */
  onDismiss?: () => void;
  /** Horizontal alignment of the banner content */
  align?: 'start' | 'center';
  /** Additional CSS classes */
  className?: string;
};

export interface BannerProps
  extends BannerOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof BannerOwnProps> {}

const defaultIcons: Record<string, string> = {
  info: 'info',
  positive: 'check_circle',
  warning: 'warning',
  error: 'error',
  neutral: 'campaign',
};

/**
 * Full-width status strip for page-level announcements: a release notice, a
 * degraded-service warning, an environment flag. The third sibling in the
 * feedback family — Alert sits inline in the layout, Toast interrupts and
 * leaves, Banner spans the page and stays until dismissed.
 *
 * Stateless like Alert: `dismissible` shows the close control and `onDismiss`
 * reports the click; removing the banner is the consumer's render decision.
 * Forwards a ref to the root element and spreads unrecognised props onto it.
 */
export const Banner = React.forwardRef<HTMLDivElement, BannerProps>(
  (
    {
      variant = 'info',
      title,
      children,
      icon,
      action,
      dismissible = false,
      onDismiss,
      align = 'start',
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-banner';

    const classes = [
      baseClass,
      `${baseClass}--${variant}`,
      align === 'center' ? `${baseClass}--center` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const iconValue = icon || defaultIcons[variant];

    return (
      <div {...rest} ref={ref} className={classes} role="status">
        <div className={`${baseClass}__body`}>
          {typeof iconValue === 'string' ? (
            <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
              {iconValue}
            </span>
          ) : (
            <span className={`${baseClass}__icon`} aria-hidden="true">
              {iconValue}
            </span>
          )}
          <p className={`${baseClass}__content`}>
            {title && <strong className={`${baseClass}__title`}>{title}</strong>}
            {title && children ? ' ' : null}
            {children}
          </p>
          {action && <span className={`${baseClass}__action`}>{action}</span>}
        </div>

        {dismissible && (
          <button
            type="button"
            className={`${baseClass}__dismiss`}
            onClick={onDismiss}
            aria-label="Dismiss banner"
          >
            <span className="material-symbols-rounded" aria-hidden="true">
              close
            </span>
          </button>
        )}
      </div>
    );
  },
);

Banner.displayName = 'Banner';
